export type TraitId='courage'|'altruism'|'caution'|'impulsivity'|'sociability'|'wariness';
export type Phase='hub'|'scene'|'refused'|'outcome'|'returned'|'ending';
export type Command={type:'depart'|'alternative'|'continue'|'endDay'}|{type:'choose';id:string}|{type:'override';confirmed:true}|{type:'useItem';id:'kit'|'cell'};
export interface Profile{name:string;purpose:'repair'|'medical'|'scout';keywords:string[];value:'life'|'self'|'truth'|'freedom';past:'flood'|'rescue'|'blank'|'duty'}
export interface CharacterState{traits:Record<TraitId,number>;energy:number;integrity:number;stability:number;beliefs:{fear_flooded_places:number};emotions:{fear:number;guilt:number}}
export interface Attempt{choiceId:string;decision:string}
export interface EventResolution{eventInstanceId:string;eventId:string;eventTitle:string;eventKind:'ambient'|'main';gameDay:number;playerChoiceId:string;intendedActionId:string;actualActionId:string;outcomeId:string;result:'success'|'partial'|'failure'|'abandoned';forcedOverrideUsed:boolean;itemUses:{itemId:string;count:number}[];outcomeTags:string[];decision:string;attempts:Attempt[];before:CharacterState;after:CharacterState}
export interface SaveData{saveVersion:2;runId:string;revision:number;day:number;dayEventIndex:0|1;rngState:number;phase:Phase;profile:Profile;character:CharacterState;inventory:Record<'drone'|'override'|'kit'|'cell'|'sealant',number>;world:Record<string,boolean>;meters:Record<'community'|'truth'|'signal'|'isolation',number>;pending:null|{eventId:string;originalChoice:string;decision:string;score:number};currentResolution:EventResolution|null;eventLog:EventResolution[];attempts:Attempt[];memories:{id:string;day:number;eventId:string;sourceEventInstanceId:string;text:string;tags:string[]}[];diaries:{day:number;text:string;sourceEventInstanceIds:string[];templateIds:string[];voiceId:string}[];discoveries:string[];lastMessage:string;ending:null|{id:string;title:string;text:string}}
